#include <linux/slab.h>
#include <linux/ipv6.h>

struct ipv6_rt_hdr *ip6_rthdr_dup(struct ipv6_rt_hdr *src, gfp_t gfp, unsigned int *mtu, int *maxfraglen, unsigned int fragheaderlen, struct sk_buff *skb, struct rt6_info *rt, bool pmtuprobe) {
    if (!src) {
        return NULL;
    }

    size_t size = sizeof(struct ipv6_rt_hdr) + src->hdrlen * 8;
    struct ipv6_rt_hdr *dup = kzalloc(size, gfp);
    if (!dup) {
        return NULL;
    }

    memcpy(dup, src, size);

    if (pmtuprobe && skb && mtu && maxfraglen) {
        unsigned int mtu_value = *mtu;
        int maxfraglen_value = *maxfraglen;

        if (mtu_value > 0 && maxfraglen_value > 0) {
            unsigned int fraglen = mtu_value - fragheaderlen;
            if (fraglen < 8) {
                fraglen = 8;
            }
            if (fraglen < maxfraglen_value) {
                *maxfraglen = fraglen;
            }
        }
    }

    return dup;
}
